 22	    uint32_t width = BSP_LCD_GetXSize();
 23	    uint32_t *fb = (uint32_t *)LCD_FB_START_ADDRESS;
 24	
 25	    for (uint32_t r = 0; r < LOGO_PTIT_HEIGHT; r++) {
 26	        for (uint32_t c = 0; c < LOGO_PTIT_WIDTH; c++) {
