 38	static void UI_DrawButton(uint16_t x, uint16_t y, uint16_t w, uint16_t h,
 39	                          uint32_t bg_color, uint32_t border_color, uint32_t text_color,
 40	                          sFONT *font, const char *label)
 41	{
 42	    /* 1. Nen nut */
 43	    BSP_LCD_SetTextColor(bg_color);
 44	    BSP_LCD_FillRect(x, y, w, h);
 45	
 46	    /* 2. Khung vien nut ro net */
 47	    BSP_LCD_SetTextColor(border_color);
 48	    BSP_LCD_DrawRect(x, y, w, h);
 49	    BSP_LCD_DrawRect(x + 1, y + 1, w - 2, h - 2);
 50	
 51	    /* 3. Can chu o chinh giua hop nut */
 52	    uint32_t len = 0;
 53	    while (label[len] != '\0') {
 54	        len++;
 55	    }
 56	    uint16_t text_width = len * font->Width;
 57	    uint16_t text_x = x + ((w > text_width) ? ((w - text_width) / 2) : 0);
 58	    uint16_t text_y = y + ((h > font->Height) ? ((h - font->Height) / 2) : 0);
 59	
 60	    BSP_LCD_SetBackColor(bg_color);
 61	    BSP_LCD_SetTextColor(text_color);
 62	    BSP_LCD_SetFont(font);
 63	    BSP_LCD_DisplayStringAt(text_x, text_y, (uint8_t *)label, LEFT_MODE);
 64	}
