163	int UI_HandleTouch(uint16_t x, uint16_t y)
164	{
165	    /* Kiem tra cham trong vung nut bam theo f-nguoi-67015084: x=160..640, y=390..450 */
166	    int in_x = (x >= 150 && x <= 650);
167	    int in_y = ((y >= 380 && y <= 460) || (y >= 20 && y <= 100));
168	    int in_swap = (y >= 150 && y <= 650) && ((x >= 380 && x <= 460) || (x >= 20 && x <= 100));
169	
170	    if ((in_x && in_y) || in_swap) {
171	        UI_ToggleScreen();
172	        return 1;
173	    }
174	    return 0;
175	}

