 23	/* Cung cấp hàm thời gian HAL dựa trên FreeRTOS tick */
 24	uint32_t HAL_GetTick(void)
 25	{
 26	    if (xTaskGetSchedulerState() != taskSCHEDULER_NOT_STARTED) {
 27	        return (uint32_t)xTaskGetTickCount();
 28	    }
 29	    static volatile uint32_t fake_tick = 0;
 30	    return ++fake_tick;
 31	}
