 33	void HAL_Delay(uint32_t Delay)
 34	{
 35	    if (xTaskGetSchedulerState() != taskSCHEDULER_NOT_STARTED) {
 36	        vTaskDelay(pdMS_TO_TICKS(Delay));
 37	    } else {
 38	        /* Vòng lặp chờ thô khi scheduler chưa khởi chạy */
 39	        for (volatile uint32_t i = 0; i < Delay * 4000; i++) {
 40	            __asm__("nop");
 41	        }
 42	    }
 43	}
