        printf("[PASS] A2: UI_State_CheckTouch(400, 425) returned 1 (HIT)\n");
        passed++;
    } else {
        printf("[FAIL] A2: Touch at (400, 425) not detected\n");
        failed++;
    }

    /* Test 3: A3 - Cham ngoai vung nut (50, 50) phai khong nhan dien (0) */
    if (UI_State_CheckTouch(50, 50) == 0) {
        printf("[PASS] A3: UI_State_CheckTouch(50, 50) returned 0 (MISS)\n");
        passed++;
    } else {
        printf("[FAIL] A3: Touch outside button (50, 50) falsely detected\n");
        failed++;
    }

    /* Test 4: A4 - Chuyen trang thai tu Main sang Details (1) */
    UI_State_Init();
    if (UI_State_Toggle() == UI_SCREEN_DETAILS) {
        printf("[PASS] A4: UI_State_Toggle transitioned from MAIN to DETAILS (1)\n");
        passed++;
    } else {
        printf("[FAIL] A4: UI_State_Toggle did not transition to DETAILS\n");
        failed++;
    }

    /* Test 5: A5 - Chuyen trang thai tu Details quay lai Main (0) */
