        printf("[PASS] A5: UI_State_Toggle transitioned from DETAILS back to MAIN (0)\n");
        passed++;
    } else {
        printf("[FAIL] A5: UI_State_Toggle did not return to MAIN\n");
        failed++;
    }

    /* Test 6: A6 - Toa do hoan doi truc (y=400, x=425) do huong cam ung FT6206 */
    if (UI_State_CheckTouch(425, 400) == 1) {
        printf("[PASS] A6: UI_State_CheckTouch with swapped axis returned 1\n");
        passed++;
    } else {
        printf("[FAIL] A6: Swapped axis touch not recognized\n");
        failed++;
    }

    printf("\n=== SUMMARY: Total 6, Passed: %d, Failed: %d ===\n", passed, failed);

    if (failed == 0) {
        return 0;
    }
    return 1;
}

